 55	        ObjectMapper objectMapper = new ObjectMapper();
 56	        objectMapper.registerModule(new JavaTimeModule());
 57	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 58	
 59	        Javalin app = Javalin.create(config -> {
 60	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 61	        });
 62	
 63	        app.get("/rooms", roomController::listRooms);
 64	        app.post("/reservations", reservationController::createReservation);
 65	        app.get("/reservations/{id}", reservationController::getReservation);
 66	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 67	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 68	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 69	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 70	        app.get("/reservations/{id}/document", reservationController::getDocument);
 71	        app.get("/messages", messageController::listMessages);
 72	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 73	        app.get("/reports/revenue", reportController::getRevenueReport);
 74	        app.get("/reports/tourism-tax", reportController::getTourismTaxReport);
 75	        app.get("/reports/rate-plans", reportController::getRatePlansReport);
 76	
 77	        app.start(port);
 78	
 79	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 80	            app.stop();
 81	            Database.close();
 82	        }));
