172	    public void getOccupancyReport(Context ctx) {
173	        try {
174	            String dateParam = ctx.queryParam("date");
175	            if (dateParam == null) {
176	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
177	                return;
178	            }
179	
180	            LocalDate date = LocalDate.parse(dateParam);
181	            ReportGenerator report = new OccupancyReportGenerator(date, reservationRepository, totalRooms);
182	            String csv = report.generate();
183	            ctx.contentType("text/csv; charset=utf-8").result(csv);
184	        } catch (DateTimeParseException e) {
185	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
186	        }
187	    }
