254	public class ReservationController {
255	    private final ReservationService reservationService;
256	    private final RoomRepository roomRepository;
257	    private final DocumentService documentService;
258	
259	    public ReservationController(
260	            ReservationService reservationService,
261	            RoomRepository roomRepository,
262	            DocumentService documentService) {
263	        this.reservationService = reservationService;
264	        this.roomRepository = roomRepository;
265	        this.documentService = documentService;
266	    }
267	
268	    public void createReservation(Context ctx) {
269	        try {
270	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
271	
272	            Reservation reservation = new Reservation();
273	            reservation.setRoomNumber(getString(body, "roomNumber"));
274	            reservation.setGuestName(getString(body, "guestName"));
275	            reservation.setGuestEmail(getString(body, "guestEmail"));
276	            reservation.setGuestCpf(getString(body, "guestCpf"));
277	            reservation.setCheckIn(getDate(body, "checkIn"));
278	            reservation.setCheckOut(getDate(body, "checkOut"));
279	            reservation.setGuests(getInt(body, "guests"));
280	            reservation.setRatePlan(RatePlan.valueOf(getString(body, "ratePlan")));
281	
282	            Reservation created = reservationService.createReservation(reservation);
283	            ctx.status(201).json(toDto(created));
284	        } catch (ReservationService.RoomNotFoundException e) {
285	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
286	        } catch (ReservationService.CapacityExceededException e) {
287	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
288	        } catch (ReservationService.RoomUnavailableException e) {
289	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
290	        } catch (ReservationService.InvalidRequestException e) {
291	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
292	        } catch (Exception e) {
293	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request format"));
294	        }
295	    }
296	
297	    public void getReservation(Context ctx) {
298	        try {
299	            Long id = Long.parseLong(ctx.pathParam("id"));
300	            Reservation reservation = reservationService.findById(id);
301	            ctx.json(toDto(reservation));
302	        } catch (ReservationService.ReservationNotFoundException e) {
303	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
304	        }
305	    }
306	
307	    public void confirmReservation(Context ctx) {
308	        try {
309	            Long id = Long.parseLong(ctx.pathParam("id"));
310	            Reservation reservation = reservationService.confirmReservation(id);
311	            ctx.json(toDto(reservation));
312	        } catch (ReservationService.ReservationNotFoundException e) {
313	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
314	        } catch (ReservationService.OperationNotAllowedException e) {
315	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
316	        }
317	    }
318	
319	    public void cancelReservation(Context ctx) {
320	        try {
321	            Long id = Long.parseLong(ctx.pathParam("id"));
322	            Reservation reservation = reservationService.cancelReservation(id);
323	            ctx.json(toDto(reservation));
324	        } catch (ReservationService.ReservationNotFoundException e) {
325	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
326	        } catch (ReservationService.OperationNotAllowedException e) {
327	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
328	        }
329	    }
330	
331	    public void checkIn(Context ctx) {
332	        try {
333	            Long id = Long.parseLong(ctx.pathParam("id"));
334	            Reservation reservation = reservationService.checkIn(id);
335	            ctx.json(toDto(reservation));
336	        } catch (ReservationService.ReservationNotFoundException e) {
337	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
338	        } catch (ReservationService.OperationNotAllowedException e) {
339	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
340	        }
341	    }
342	
343	    public void checkOut(Context ctx) {
344	        try {
345	            Long id = Long.parseLong(ctx.pathParam("id"));
346	            Reservation reservation = reservationService.checkOut(id);
347	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
348	            Document document = documentService.createDocument(reservation, room);
349	            ctx.json(toDocumentDto(document));
350	        } catch (ReservationService.ReservationNotFoundException e) {
351	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
352	        } catch (ReservationService.OperationNotAllowedException e) {
353	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
354	        }
355	    }
356	
357	    public void getDocument(Context ctx) {
358	        try {
359	            Long id = Long.parseLong(ctx.pathParam("id"));
360	            Reservation reservation = reservationService.findById(id);
361	
362	            if (!reservation.isPaid()) {
363	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for paid reservations"));
364	                return;
365	            }
366	
367	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
368	            Document document = documentService.createDocument(reservation, room);
369	            ctx.json(toDocumentDto(document));
370	        } catch (ReservationService.ReservationNotFoundException e) {
371	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
372	        }
373	    }
374	
375	    private Map<String, Object> toDto(Reservation r) {
376	        Map<String, Object> dto = new HashMap<>();
377	        dto.put("id", r.getId());
378	        dto.put("roomNumber", r.getRoomNumber());
379	        dto.put("guestName", r.getGuestName());
380	        dto.put("guestEmail", r.getGuestEmail());
381	        dto.put("guestCpf", r.getGuestCpf());
382	        dto.put("checkIn", r.getCheckIn().toString());
383	        dto.put("checkOut", r.getCheckOut().toString());
384	        dto.put("guests", r.getGuests());
385	        dto.put("ratePlan", r.getRatePlan().name());
386	        dto.put("nights", r.getNights());
387	        dto.put("subtotal", r.getSubtotal());
388	        dto.put("discount", r.getDiscount());
389	        dto.put("total", r.getTotal());
390	        dto.put("status", r.getStatus().name());
391	        dto.put("amountPaid", r.getAmountPaid());
392	        dto.put("refund", r.getRefund());
393	        return dto;
394	    }
395	
396	    private Map<String, Object> toDocumentDto(Document doc) {
397	        Map<String, Object> dto = new HashMap<>();
398	        dto.put("title", doc.getTitle());
399	        dto.put("reservationId", doc.getReservationId());
400	        dto.put("guestName", doc.getGuestName());
401	        dto.put("guestCpf", doc.getGuestCpf());
402	        dto.put("roomNumber", doc.getRoomNumber());
403	        dto.put("roomType", doc.getRoomType().name());
404	        dto.put("checkIn", doc.getCheckIn().toString());
405	        dto.put("checkOut", doc.getCheckOut().toString());
406	        dto.put("nights", doc.getNights());
407	        dto.put("subtotal", doc.getSubtotal());
408	        dto.put("discount", doc.getDiscount());
409	        dto.put("total", doc.getTotal());
410	        return dto;
411	    }
412	
413	    private String getString(Map<String, Object> map, String key) {
414	        Object value = map.get(key);
415	        if (value == null) {
416	            throw new IllegalArgumentException("Missing field: " + key);
417	        }
418	        return value.toString();
419	    }
420	
421	    private int getInt(Map<String, Object> map, String key) {
422	        Object value = map.get(key);
423	        if (value == null) {
424	            throw new IllegalArgumentException("Missing field: " + key);
425	        }
426	        if (value instanceof Number) {
427	            return ((Number) value).intValue();
428	        }
429	        return Integer.parseInt(value.toString());
430	    }
431	
432	    private LocalDate getDate(Map<String, Object> map, String key) {
433	        try {
434	            return LocalDate.parse(getString(map, key));
435	        } catch (DateTimeParseException e) {
436	            throw new IllegalArgumentException("Invalid date format for " + key);
437	        }
438	    }
439	}
