 63	
 64	import com.pousadamarealta.domain.RatePlan;
 65	import com.pousadamarealta.domain.Reservation;
 66	import com.pousadamarealta.repository.ReservationRepository;
 67	
 68	import java.math.BigDecimal;
 69	import java.time.YearMonth;
 70	import java.util.List;
 71	import java.util.Map;
 72	import java.util.stream.Collectors;
 73	
 74	public class RatePlansReportGenerator extends ReportGenerator {
 75	    private final YearMonth month;
 76	    private final ReservationRepository reservationRepository;
 77	
 78	    public RatePlansReportGenerator(YearMonth month, ReservationRepository reservationRepository) {
 79	        this.month = month;
 80	        this.reservationRepository = reservationRepository;
 81	    }
 82	
 83	    @Override
 84	    protected String getReportName() {
 85	        return "rate-plans";
 86	    }
 87	
 88	    @Override
 89	    protected String getPeriod() {
 90	        return formatMonth(month);
 91	    }
 92	
 93	    @Override
 94	    protected String buildHeaderLine() {
 95	        return "rate_plan,reservations,amount";
 96	    }
 97	
 98	    @Override
 99	    protected String buildDataLines() {
100	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
101	
102	        Map<RatePlan, List<Reservation>> byPlan = reservations.stream()
103	            .filter(r -> r.getNetRevenue().compareTo(BigDecimal.ZERO) > 0)
104	            .collect(Collectors.groupingBy(Reservation::getRatePlan));
105	
106	        StringBuilder lines = new StringBuilder();
107	
108	        for (RatePlan plan : RatePlan.values()) {
109	            List<Reservation> planReservations = byPlan.getOrDefault(plan, List.of());
110	            long count = planReservations.size();
111	            BigDecimal amount = planReservations.stream()
112	                .map(Reservation::getNetRevenue)
113	                .reduce(BigDecimal.ZERO, BigDecimal::add);
114	
115	            lines.append(plan.name()).append(",");
116	            lines.append(count).append(",");
117	            lines.append(formatDecimal(amount)).append("\n");
118	        }
119	
120	        return lines.toString();
121	    }
122	
123	    @Override
124	    protected String buildTotalLine() {
125	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
126	
127	        long totalCount = reservations.stream()
128	            .filter(r -> r.getNetRevenue().compareTo(BigDecimal.ZERO) > 0)
129	            .count();
130	
131	        BigDecimal totalAmount = reservations.stream()
132	            .map(Reservation::getNetRevenue)
133	            .filter(amount -> amount.compareTo(BigDecimal.ZERO) > 0)
134	            .reduce(BigDecimal.ZERO, BigDecimal::add);
135	
136	        return "total," + totalCount + "," + formatDecimal(totalAmount);
137	    }
138	}
