141	import java.math.BigDecimal;
142	import java.text.DecimalFormat;
143	import java.text.DecimalFormatSymbols;
144	import java.time.LocalDate;
145	import java.time.YearMonth;
146	import java.time.format.DateTimeFormatter;
147	import java.util.Locale;
148	
149	public abstract class ReportGenerator {
150	    protected static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
151	    protected static final DecimalFormat DECIMAL_FORMAT;
152	
153	    static {
154	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
155	        symbols.setDecimalSeparator('.');
156	        DECIMAL_FORMAT = new DecimalFormat("0.00", symbols);
157	    }
158	
159	    public final String generate() {
160	        StringBuilder csv = new StringBuilder();
161	        csv.append(buildTitleLine()).append("\n");
162	        csv.append(buildHeaderLine()).append("\n");
163	        csv.append(buildDataLines());
164	        csv.append(buildTotalLine()).append("\n");
165	        return csv.toString();
166	    }
167	
168	    protected abstract String getReportName();
169	    protected abstract String getPeriod();
170	    protected abstract String buildHeaderLine();
171	    protected abstract String buildDataLines();
172	    protected abstract String buildTotalLine();
173	
174	    private String buildTitleLine() {
175	        return "Pousada Maré Alta," + getReportName() + "," + getPeriod();
176	    }
177	
178	    protected String formatDecimal(BigDecimal value) {
179	        return DECIMAL_FORMAT.format(value);
180	    }
181	
182	    protected String formatDate(LocalDate date) {
183	        return date.format(DATE_FORMAT);
184	    }
185	
186	    protected String formatMonth(YearMonth month) {
187	        return month.format(DateTimeFormatter.ofPattern("yyyy-MM"));
188	    }
189	}
