355	        sb.append("Hóspede: ").append(doc.getGuestName());
356	        sb.append(" (CPF ").append(formatCpf(doc.getGuestCpf())).append(")\n");
357	        sb.append("Quarto: ").append(doc.getRoomNumber());
358	        sb.append(" (").append(doc.getRoomType().name()).append(")\n");
359	        sb.append("Entrada: ").append(doc.getCheckIn().format(DATE_FORMAT));
360	        sb.append(" | Saída: ").append(doc.getCheckOut().format(DATE_FORMAT));
361	        sb.append(" | ").append(doc.getNights()).append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
362	        sb.append("Diárias: ").append(CURRENCY_FORMAT.format(doc.getSubtotal())).append("\n");
363	
364	        if (doc.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
365	            sb.append("Desconto: ").append(CURRENCY_FORMAT.format(doc.getDiscount())).append("\n");
