412	import com.pousadamarealta.domain.RatePlan;
413	import com.pousadamarealta.domain.Room;
414	
415	import java.math.BigDecimal;
416	import java.math.RoundingMode;
417	import java.time.LocalDate;
418	
419	public class PricingService {
420	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
421	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
422	
423	    public BigDecimal calculateNightPrice(Room room, LocalDate date) {
424	        BigDecimal basePrice = room.getNightlyRate();
425	        if (isHighSeason(date)) {
426	            return basePrice.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
427	        }
428	        return basePrice;
429	    }
430	
431	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
432	        BigDecimal subtotal = BigDecimal.ZERO;
433	        LocalDate date = checkIn;
434	        while (date.isBefore(checkOut)) {
435	            BigDecimal nightPrice = calculateNightPrice(room, date);
436	            subtotal = subtotal.add(nightPrice);
437	            date = date.plusDays(1);
438	        }
439	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
440	    }
441	
442	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
443	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
444	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
445	        }
446	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
447	    }
448	
449	    private boolean isHighSeason(LocalDate date) {
450	        int month = date.getMonthValue();
451	        int day = date.getDayOfMonth();
452	
453	        if (month == 7) {
454	            return true;
455	        }
456	
457	        if (month == 12 && day >= 15) {
458	            return true;
459	        }
460	
461	        if (month == 1 || month == 2) {
462	            return true;
463	        }
464	
465	        return false;
466	    }
467	}
