480	    private final RoomRepository roomRepository;
481	    private final PricingService pricingService;
482	    private final DocumentService documentService;
483	    private final MessageService messageService;
484	
485	    public ReservationService(
486	            ReservationRepository reservationRepository,
487	            RoomRepository roomRepository,
488	            PricingService pricingService,
489	            DocumentService documentService,
490	            MessageService messageService) {
491	        this.reservationRepository = reservationRepository;
492	        this.roomRepository = roomRepository;
493	        this.pricingService = pricingService;
494	        this.documentService = documentService;
495	        this.messageService = messageService;
496	    }
497	
498	    public Reservation createReservation(Reservation reservation) {
499	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
500	            .orElseThrow(() -> new RoomNotFoundException());
501	
502	        if (reservation.getGuests() < 1) {
503	            throw new InvalidRequestException("At least one guest is required");
504	        }
505	
506	        if (reservation.getGuests() > room.getCapacity()) {
507	            throw new CapacityExceededException();
508	        }
509	
510	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
511	            reservation.getCheckOut().equals(reservation.getCheckIn())) {
512	            throw new InvalidRequestException("Check-out must be after check-in");
513	        }
514	
515	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(
516	            reservation.getRoomNumber(),
517	            reservation.getCheckIn(),
518	            reservation.getCheckOut()
519	        );
520	
521	        if (!conflicts.isEmpty()) {
522	            throw new RoomUnavailableException();
523	        }
524	
525	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
526	        reservation.setNights(nights);
527	
528	        BigDecimal subtotal = pricingService.calculateSubtotal(room, reservation.getCheckIn(), reservation.getCheckOut());
529	        reservation.setSubtotal(subtotal);
530	
531	        BigDecimal discount = pricingService.calculateDiscount(subtotal, reservation.getRatePlan());
532	        reservation.setDiscount(discount);
533	
534	        BigDecimal total = subtotal.subtract(discount);
535	        reservation.setTotal(total);
536	
537	        return reservationRepository.save(reservation);
538	    }
539	
540	    public Reservation confirmReservation(Long id) {
541	        Reservation reservation = reservationRepository.findById(id)
542	            .orElseThrow(() -> new ReservationNotFoundException());
543	
544	        if (reservation.getStatus() != ReservationStatus.PENDING) {
545	            throw new OperationNotAllowedException();
546	        }
547	
548	        reservation.setStatus(ReservationStatus.CONFIRMED);
549	        reservation.setAmountPaid(reservation.getTotal());
550	        reservationRepository.save(reservation);
551	
552	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
553	        Document document = documentService.createDocument(reservation, room);
554	        String receipt = documentService.formatDocument(document);
555	        String emailBody = messageService.createConfirmationEmail(reservation.getGuestName(), receipt);
556	
557	        messageService.sendEmail(
558	            reservation.getGuestEmail(),
559	            "Reserva confirmada - Pousada Maré Alta",
560	            emailBody
561	        );
562	
563	        return reservation;
564	    }
565	
566	    public Reservation cancelReservation(Long id) {
567	        Reservation reservation = reservationRepository.findById(id)
568	            .orElseThrow(() -> new ReservationNotFoundException());
569	
570	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
571	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
572	            reservation.getStatus() == ReservationStatus.CANCELLED) {
573	            throw new OperationNotAllowedException();
574	        }
575	
576	        reservation.setStatus(ReservationStatus.CANCELLED);
577	
578	        if (reservation.getRatePlan() == RatePlan.STANDARD &&
579	            reservation.getAmountPaid().compareTo(BigDecimal.ZERO) > 0) {
580	            reservation.setRefund(reservation.getAmountPaid());
581	        } else {
582	            reservation.setRefund(BigDecimal.ZERO);
583	        }
584	
585	        return reservationRepository.save(reservation);
586	    }
587	
588	    public Reservation checkIn(Long id) {
589	        Reservation reservation = reservationRepository.findById(id)
590	            .orElseThrow(() -> new ReservationNotFoundException());
591	
592	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
593	            throw new OperationNotAllowedException();
594	        }
595	
596	        reservation.setStatus(ReservationStatus.CHECKED_IN);
597	        return reservationRepository.save(reservation);
598	    }
599	
600	    public Reservation checkOut(Long id) {
601	        Reservation reservation = reservationRepository.findById(id)
602	            .orElseThrow(() -> new ReservationNotFoundException());
603	
604	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
605	            throw new OperationNotAllowedException();
606	        }
607	
608	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
609	        return reservationRepository.save(reservation);
610	    }
