283	        return "reservation,room,check_in,check_out,guests,nights,tax";
284	    }
285	
286	    @Override
287	    protected String buildDataLines() {
288	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
289	        StringBuilder lines = new StringBuilder();
290	        for (Reservation r : reservations) {
291	            if (r.isPaid()) {
292	                BigDecimal tax = calculateTax(r);
293	                lines.append(r.getId()).append(",");
294	                lines.append(r.getRoomNumber()).append(",");
295	                lines.append(formatDate(r.getCheckIn())).append(",");
296	                lines.append(formatDate(r.getCheckOut())).append(",");
297	                lines.append(r.getGuests()).append(",");
298	                lines.append(r.getNights()).append(",");
299	                lines.append(formatDecimal(tax)).append("\n");
300	            }
301	        }
302	        return lines.toString();
303	    }
304	
305	    @Override
306	    protected String buildTotalLine() {
307	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
308	        BigDecimal total = reservations.stream()
309	            .filter(Reservation::isPaid)
310	            .map(this::calculateTax)
311	            .reduce(BigDecimal.ZERO, BigDecimal::add);
312	        return "total," + formatDecimal(total);
313	    }
314	
315	    private BigDecimal calculateTax(Reservation r) {
316	        return TAX_PER_GUEST_PER_NIGHT
317	            .multiply(new BigDecimal(r.getGuests()))
318	            .multiply(new BigDecimal(r.getNights()));
319	    }
320	}
