331	public class DocumentService {
332	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
333	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
334	
335	    public Document createDocument(Reservation reservation, Room room) {
336	        Document doc = new Document();
337	        doc.setTitle("Comprovante de reserva");
338	        doc.setReservationId(reservation.getId());
339	        doc.setGuestName(reservation.getGuestName());
340	        doc.setGuestCpf(reservation.getGuestCpf());
341	        doc.setRoomNumber(reservation.getRoomNumber());
342	        doc.setRoomType(room.getType());
343	        doc.setCheckIn(reservation.getCheckIn());
344	        doc.setCheckOut(reservation.getCheckOut());
345	        doc.setNights(reservation.getNights());
346	        doc.setSubtotal(reservation.getSubtotal());
347	        doc.setDiscount(reservation.getDiscount());
348	        doc.setTotal(reservation.getTotal());
349	        return doc;
350	    }
