 28	    private static void createSchema() {
 29	        String createRoomsTable = """
 30	            CREATE TABLE IF NOT EXISTS rooms (
 31	                number VARCHAR(10) PRIMARY KEY,
 32	                type VARCHAR(20) NOT NULL
 33	            )
 34	            """;
 35	
 36	        String createReservationsTable = """
 37	            CREATE TABLE IF NOT EXISTS reservations (
 38	                id SERIAL PRIMARY KEY,
 39	                room_number VARCHAR(10) NOT NULL,
 40	                guest_name VARCHAR(255) NOT NULL,
 41	                guest_email VARCHAR(255) NOT NULL,
 42	                guest_cpf VARCHAR(20) NOT NULL,
 43	                check_in DATE NOT NULL,
 44	                check_out DATE NOT NULL,
 45	                guests INTEGER NOT NULL,
 46	                rate_plan VARCHAR(20) NOT NULL,
 47	                nights INTEGER NOT NULL,
 48	                subtotal DECIMAL(10, 2) NOT NULL,
 49	                discount DECIMAL(10, 2) NOT NULL,
 50	                total DECIMAL(10, 2) NOT NULL,
 51	                status VARCHAR(20) NOT NULL,
 52	                amount_paid DECIMAL(10, 2) NOT NULL,
 53	                refund DECIMAL(10, 2),
 54	                FOREIGN KEY (room_number) REFERENCES rooms(number)
 55	            )
 56	            """;
 57	
 58	        String createMessagesTable = """
 59	            CREATE TABLE IF NOT EXISTS messages (
 60	                id SERIAL PRIMARY KEY,
 61	                channel VARCHAR(20) NOT NULL,
 62	                recipient VARCHAR(255) NOT NULL,
 63	                subject VARCHAR(500) NOT NULL,
 64	                body TEXT NOT NULL
 65	            )
 66	            """;
 67	
 68	        try (Connection conn = getConnection();
 69	             Statement stmt = conn.createStatement()) {
 70	            stmt.execute(createRoomsTable);
 71	            stmt.execute(createReservationsTable);
 72	            stmt.execute(createMessagesTable);
 73	        } catch (SQLException e) {
 74	            throw new RuntimeException("Failed to create database schema", e);
 75	        }
 76	    }
 77	
 78	    public static void close() {
 79	        if (dataSource != null) {
 80	            dataSource.close();
 81	        }
 82	    }
