160	                check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
161	                status, amount_paid, refund)
162	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
163	            RETURNING id
