178	    private void update(Reservation reservation) {
179	        String sql = """
180	            UPDATE reservations SET room_number = ?, guest_name = ?, guest_email = ?,
181	                guest_cpf = ?, check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
182	                nights = ?, subtotal = ?, discount = ?, total = ?, status = ?,
