350	        try (Connection conn = Database.getConnection();
351	             PreparedStatement stmt = conn.prepareStatement(sql)) {
352	            stmt.setString(1, number);
353	            try (ResultSet rs = stmt.executeQuery()) {
354	                if (rs.next()) {
355	                    return Optional.of(mapRow(rs));
356	                }
357	                return Optional.empty();
358	            }
359	        } catch (SQLException e) {
360	            throw new RuntimeException("Failed to find room", e);
